const row = $input.item.json;
const cnt = parseInt(row.cnt || row['count'] || 0, 10);
const finding = cnt > 0;
const summary = finding
  ? `Time Anomaly: ${cnt} open clock-in record(s) older than 12 hours. Technician(s) may have forgotten to clock out.`
  : `Time Anomaly: no open clock-ins older than 12 hours.`;
return [{ json: { finding, summary, check: 'time-anomaly', count: cnt } }];

const row = $input.item.json;
const cnt = parseInt(row.cnt || row['count'] || 0, 10);
const finding = cnt > 0;
const summary = finding
  ? `Stale Job: ${cnt} work order(s) have no tech assigned and are 3+ days old. Assign a technician in the dispatch board.`
  : `Stale Job: no unassigned jobs older than 3 days.`;
return [{ json: { finding, summary, check: 'stale-job', count: cnt } }];
